#!/usr/bin/env python3
"""Embed the checked public FSR3.1.6 FI/OF Vulkan modules as C data."""

from __future__ import annotations

import argparse
import hashlib
import struct
from pathlib import Path


MODULES = (
    "fsr3_3_1_6_fi_ffx_frameinterpolation_reconstruct_and_dilate.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation_setup.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation_reconstruct_previous_depth.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation_game_motion_vector_field.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation_optical_flow_vector_field.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation_disocclusion_mask.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation_compute_inpainting_pyramid.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation_inpainting.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation_compute_game_vector_field_inpainting_pyramid.spv",
    "fsr3_3_1_6_fi_ffx_frameinterpolation_debug_view.spv",
    "fsr3_3_1_6_of_ffx_opticalflow_prepare_luma.spv",
    "fsr3_3_1_6_of_ffx_opticalflow_compute_luminance_pyramid.spv",
    "fsr3_3_1_6_of_ffx_opticalflow_generate_scd_histogram.spv",
    "fsr3_3_1_6_of_ffx_opticalflow_compute_scd_divergence.spv",
    "fsr3_3_1_6_of_ffx_opticalflow_compute_optical_flow_advanced_pass_v5.spv",
    "fsr3_3_1_6_of_ffx_opticalflow_filter_optical_flow_pass_v5.spv",
    "fsr3_3_1_6_of_ffx_opticalflow_scale_optical_flow_advanced_pass_v5.spv",
)


def identifier(filename: str) -> str:
    return filename.removesuffix(".spv").upper()


def words(data: bytes) -> str:
    values = struct.unpack(f"<{len(data) // 4}I", data)
    return "\n".join(
        "    " + ", ".join(f"UINT32_C(0x{value:08x})" for value in values[start:start + 8]) + ","
        for start in range(0, len(values), 8)
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("input_directory", type=Path)
    parser.add_argument("output_header", type=Path)
    args = parser.parse_args()

    payloads: list[tuple[str, bytes]] = []
    for filename in MODULES:
        data = (args.input_directory / filename).read_bytes()
        if not data or len(data) % 4 or struct.unpack_from("<I", data)[0] != 0x07230203:
            raise SystemExit(f"invalid SPIR-V: {filename}")
        payloads.append((filename, data))

    lines = [
        "/* Auto-generated by package_fsr3_3_1_6_framegen_spirv.py; do not edit. */",
        "#ifndef FFX_VK_FSR3_3_1_6_FRAMEGEN_EMBEDDED_SPIRV_H",
        "#define FFX_VK_FSR3_3_1_6_FRAMEGEN_EMBEDDED_SPIRV_H",
        "#include <stdint.h>",
        "#include <stddef.h>",
        "typedef struct FfxVkFsr3_3_1_6FramegenEmbeddedSpirv {",
        "    const char* filename;",
        "    const uint32_t* words;",
        "    size_t wordCount;",
        "} FfxVkFsr3_3_1_6FramegenEmbeddedSpirv;",
    ]
    for filename, data in payloads:
        symbol = f"FFX_VK_FSR3_3_1_6_{identifier(filename)}"
        lines.extend((f"static const uint32_t {symbol}[] = {{", words(data), "};"))
    lines.append("static const FfxVkFsr3_3_1_6FramegenEmbeddedSpirv FFX_VK_FSR3_3_1_6_FRAMEGEN_EMBEDDED_SPIRV[] = {")
    for filename, _ in payloads:
        symbol = f"FFX_VK_FSR3_3_1_6_{identifier(filename)}"
        lines.append(f'    {{"{filename}", {symbol}, sizeof({symbol}) / sizeof({symbol}[0])}},')
    lines.extend((
        "};",
        f"#define FFX_VK_FSR3_3_1_6_FRAMEGEN_EMBEDDED_SPIRV_COUNT {len(payloads)}u",
        "#endif",
        "",
    ))
    args.output_header.write_text("\n".join(lines), encoding="utf-8")
    manifest = "\n".join(
        f"{hashlib.sha256(data).hexdigest()}  {filename}" for filename, data in payloads
    )
    (args.output_header.parent / "EMBEDDED_SOURCE_SHA256SUMS").write_text(manifest + "\n", encoding="ascii")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
